# Better extract first meaningful user prompt from today's transcript dirs by mtime Oct 26
python3 - <<'PY'
import json, os, re
from datetime import datetime
base="/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts"
# only dirs with mtime on Oct 26 (local)
import time
for name in sorted(os.listdir(base), key=lambda n: os.path.getmtime(os.path.join(base,n)), reverse=True):
  d=os.path.join(base,name)
  if not os.path.isdir(d): continue
  mt=os.path.getmtime(d)
  ds=datetime.fromtimestamp(mt).strftime('%Y-%m-%d %H:%M')
  if not ds.startswith('2026-10-26') and not ds.startswith('2026-10-25'):
    continue
  p=os.path.join(d, name+'.jsonl')
  if not os.path.exists(p):
    files=[f for f in os.listdir(d) if f.endswith('.jsonl')]
    p=os.path.join(d, files[0]) if files else None
  if not p: continue
  first_user=None; last_texts=[]
  with open(p,encoding='utf-8',errors='replace') as f:
    for line in f:
      try:o=json.loads(line)
      except: continue
      # Cursor agent transcript format: {"role":"user"|"assistant", "message":{"content":[...]}}
      role=o.get('role')
      msg=o.get('message') or {}
      content=msg.get('content') if isinstance(msg,dict) else None
      texts=[]
      if isinstance(content,list):
        for c in content:
          if isinstance(c,dict) and c.get('type')=='text':
            texts.append(c.get('text') or '')
      elif isinstance(content,str):
        texts=[content]
      text='\n'.join(texts).strip()
      if not text: continue
      # skip system/tool dumps somewhat
      if role=='user' and first_user is None:
        # strip XML-ish wrappers for display
        t=re.sub(r'<[^>]+>',' ', text)
        t=re.sub(r'\s+',' ', t).strip()[:280]
        if 'AGENT_LOOP' in text or '定时·日报' in text or 'REMIND' in text:
          first_user=('[WAKE] '+t[:200])
        else:
          first_user=t
      if role=='assistant':
        t=re.sub(r'<[^>]+>',' ', text)
        t=re.sub(r'\s+',' ', t).strip()
        if t and len(t)>40:
          last_texts.append(t[:300])
  print(f"\n## {name} mtime={ds}")
  print("USER:", first_user)
  if last_texts:
    print("ASST_LAST:", last_texts[-1])
PY

